import functools

registry = []

def trace(func):
    print("decorating", func.__name__)          # runs at definition time
    registry.append(func.__name__)
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print("call", func.__name__, args)      # runs on every call
        result = func(*args, **kwargs)
        return result                           # do not forget to return
    return wrapper

print("-- defining --")
@trace
def add(a, b):
    return a + b

@trace
def mul(a, b):
    return a * b

print("-- calling --")
print("add:", add(2, 3))
print("mul:", mul(4, 5))
print("registry:", registry)

# Stacking: applied bottom-up, executed top-down
def tag(name):
    def deco(f):
        def w(*a):
            print("enter", name)
            return f(*a)
        return w
    return deco

@tag("outer")
@tag("inner")
def hello():
    return "hello"
print(hello())

import functools, inspect

def plain(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def good(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@plain
def a(x, y=1):
    """Add things."""
    return x + y

@good
def b(x, y=1):
    """Add things."""
    return x + y

print("plain:", a.__name__, repr(a.__doc__), inspect.signature(a))
print("wraps:", b.__name__, repr(b.__doc__), inspect.signature(b))
print("has __wrapped__:", hasattr(b, "__wrapped__"))
print("unwrap is original:", inspect.unwrap(b) is b.__wrapped__)
print("b(2) =", b(2), "| original:", b.__wrapped__(2))

import functools

def retry(func=None, *, times=3):
    if func is None:                         # used as @retry(times=2)
        return functools.partial(retry, times=times)
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for attempt in range(1, times + 1):
            try:
                return func(*args, **kwargs)
            except ValueError as e:
                print("  attempt", attempt, "failed:", e)
                if attempt == times:
                    raise                    # keep the original exception
    return wrapper

calls = {"n": 0}

@retry(times=3)
def flaky():
    calls["n"] += 1
    if calls["n"] < 3:
        raise ValueError("boom %d" % calls["n"])
    return "ok after %d calls" % calls["n"]

@retry
def always_bad():
    raise ValueError("never works")

print(flaky())
try:
    always_bad()
except ValueError as e:
    print("gave up:", e)

import functools

@functools.lru_cache(maxsize=2)
def square(n):
    print("  computing", n)
    return n * n

print(square(2), square(3))
print(square(2))                 # hit, no "computing"
print(square(4))                 # evicts least recently used (3)
print(square(3))                 # miss again
print(square.cache_info())

@functools.cache
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
print("fib(50) =", fib(50))

