import functools, types

class CountCalls:
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.count = 0
    def __call__(self, *args, **kwargs):
        self.count += 1
        return self.func(*args, **kwargs)
    def __get__(self, instance, owner):          # makes methods work
        if instance is None:
            return self
        return types.MethodType(self, instance)  # binds self

@CountCalls
def hello(name):
    return "hello " + name

class Greeter:
    def __init__(self, who):
        self.who = who
    @CountCalls
    def greet(self):
        return "hi " + self.who

print(hello("a"), hello("b"), "calls:", hello.count)
print(Greeter("sam").greet(), "calls:", Greeter.greet.count)

class NoGet:
    def __init__(self, f):
        self.f = f
    def __call__(self, *a):
        return self.f(*a)
class Bad:
    @NoGet
    def m(self):
        return "x"
try:
    Bad().m()
except TypeError as e:
    print("without __get__:", e)
